actions.script:
from = from || 'now-7d'; thru = thru || 'now'
const result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters({
    datasetId: 'otel_errors', from, thru, queryString: queryString || '',
    sort: [order === 'oldest' ? 'time' : '-time'], pageIndex: parseInt(pageIndex || '0', 10), pageSize: parseInt(pageSize || '50', 10)
}).call()
const stamp = value => { const date = new Date(/^\d+$/.test(String(value)) ? Number(value) : value); return value == null || Number.isNaN(date.getTime()) ? String(value ?? '') : ec.l10n.format(date, 'yyyy-MM-dd HH:mm:ss') }
documentList = (result.hits || []).map(hit => { const body = hit.body || {}; return Object.assign({documentId:hit.documentId || hit.id},body,{
    messageText:String(body.message || body['exception.type'] || 'Error group').slice(0,200),exceptionType:body['exception.type'] || '',serviceName:body['service.name'] || '',firstSeenText:stamp(body.first_seen),lastSeenText:stamp(body.last_seen)}) })
documentListCount = result.total || 0
documentListPageIndex = parseInt(pageIndex || '0', 10)
documentListPageSize = parseInt(pageSize || '50', 10)
documentListPageMaxIndex = Math.max(0,Math.ceil(documentListCount / documentListPageSize)-1)
documentListPageRangeLow = documentList.length ? documentListPageIndex*documentListPageSize+1 : 0
documentListPageRangeHigh = documentListPageIndex*documentListPageSize+documentList.length
queryNotices = (result.notices || []).map(notice=>typeof notice==='string'?notice:notice.message || JSON.stringify(notice))
// Error groups hold totals, so the chart counts the failed spans: a request's SERVER span or a job's root span.
// The current, partial bucket stays (marked partial): the newest failures matter most.
errorsFrame = {fields:[]}
try {
    const overTime = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:{datasetId:'otel_spans',from,thru,
        filters:[{field:{name:'status_code',op:'eq',value:'ERROR'}},{bool:{any:[{field:{name:'kind',op:'eq',value:'SERVER'}},{field:{name:'moqui.job.root',op:'eq',value:true}}]}}],
        aggregations:[{id:'time',type:'date_histogram',role:'x-axis',params:{field:'start',interval:'auto',targetBars:60,min_doc_count:0,drop_partial:false}},
            {id:'service',type:'terms',role:'series',params:{field:'service.name',size:10,missing:'(unknown)'}}]}}).call()
    errorsFrame = (overTime.frames || [])[0] || {fields:[]}
    queryNotices.push(...(overTime.notices || []).map(notice=>typeof notice==='string'?notice:notice.message || JSON.stringify(notice)))
} catch (error) { ec.logger.error('Errors over time failed: '+String(error)); queryNotices.push(String(error)) }
errorsPanel = {title:'Failed requests and jobs over time',visualization:'timeSeries',queries:[{aggregations:[{id:'time',role:'x-axis'},{id:'service',role:'series'},{id:'count',role:'metric'}]}]}
